/**
 * Bilingual strings for Iqra app (Arabic / English).
 * Default language: Arabic (ar).
 * Usage: const { t } = useLanguage(); then t('key')
 */

import { arCountPhrase, arMarksPhrase, arQuestionsPhrase, enMarksPhrase } from './arCount.ts';
import { formatMarks } from './studentAnswers.ts';

export type Lang = 'ar' | 'en';

/**
 * Count students the way Arabic actually does it.
 *
 * Arabic inflects a counted noun by number class rather than a single
 * singular/plural split: one takes the noun alone, two takes the dual, three to
 * ten take the plural, and eleven upward return to the singular in the
 * accusative. Substituting a digit into one fixed template gets three of those
 * four cases wrong, which reads as broken Arabic to a teacher.
 */
export function arCountStudents(n: number): string {
  if (n === 0) return 'لا طلبة';
  if (n === 1) return 'طالب واحد';
  if (n === 2) return 'طالبان';
  if (n >= 3 && n <= 10) return `${n} طلبة`;
  return `${n} طالبًا`;
}

/** English side of the same count, so screens have one call for both. */
export function enCountStudents(n: number): string {
  if (n === 0) return 'No students';
  return `${n} ${n === 1 ? 'student' : 'students'}`;
}

/** Count students in the active language. */
export function countStudents(n: number, lang: Lang): string {
  return lang === 'ar' ? arCountStudents(n) : enCountStudents(n);
}

/** Same four-case rule as arCountStudents, for a count of sections. */
export function arCountClasses(n: number): string {
  if (n === 0) return 'لا شُعَب';
  if (n === 1) return 'شعبة واحدة';
  if (n === 2) return 'شعبتان';
  if (n >= 3 && n <= 10) return `${n} شُعَب`;
  return `${n} شعبةً`;
}

/** English side of the same count. */
export function enCountClasses(n: number): string {
  if (n === 0) return 'No classes';
  return `${n} ${n === 1 ? 'class' : 'classes'}`;
}

/** Count classes in the active language. */
export function countClasses(n: number, lang: Lang): string {
  return lang === 'ar' ? arCountClasses(n) : enCountClasses(n);
}

/** Same four-case rule as arCountStudents, for materials attached to a class. */
export function arCountMaterials(n: number): string {
  if (n === 0) return 'لا ملفات';
  if (n === 1) return 'ملف واحد';
  if (n === 2) return 'ملفان';
  if (n >= 3 && n <= 10) return `${n} ملفات`;
  return `${n} ملفًا`;
}

/** Count materials in the active language. */
export function countMaterials(n: number, lang: Lang): string {
  if (lang === 'ar') return arCountMaterials(n);
  if (n === 0) return 'No files';
  return `${n} ${n === 1 ? 'file' : 'files'}`;
}

/**
 * Same four-case rule again, for the elapsed-seconds counter on a generation
 * that is still running. "1 ثانية" and "3 ثانية" are both wrong Arabic, and a
 * counter ticking once a second is the most-read string on the screen while a
 * teacher waits.
 */
export function arCountSeconds(n: number): string {
  if (n === 1) return 'ثانية واحدة';
  if (n === 2) return 'ثانيتان';
  if (n >= 3 && n <= 10) return `${n} ثوانٍ`;
  return `${n} ثانية`;
}

/** Count seconds in the active language. */
export function countSeconds(n: number, lang: Lang): string {
  if (lang === 'ar') return arCountSeconds(n);
  return `${n}s`;
}

/** Arabic-Indic digits for the live game's counted phrases (display only). */
const liveAr = (n: number | string) => String(n).replace(/[0-9]/g, d => '٠١٢٣٤٥٦٧٨٩'[Number(d)]!);

